var line = msg.payload;
if (typeof line !== 'string') return null;

var match = line.match(/\s+can\d+\s+([0-9A-Fa-f]+)\s+\[(\d)\]\s+(.+)/);
if (!match) return null;

var rawid = parseInt(match[1], 16);
var canid = rawid & 0x7FF;
var dlc = parseInt(match[2]);
var hexBytes = match[3].trim().split(/\s+/);
var data = Buffer.from(hexBytes.map(function(h) { return parseInt(h, 16); }));

msg.payload = { canid: canid, dlc: dlc, data: data };
msg.topic = "0x" + canid.toString(16).toUpperCase();
return msg;

var id = msg.payload.canid;
var d = msg.payload.data;

if (id < 0x351 || id > 0x404) return null;

var bms = flow.get("bms_live") || {};
bms._lastUpdate = Date.now();
var decoded = { canId: "0x" + id.toString(16).toUpperCase() };

switch (id) {
    case 0x351:
        bms.cvl = d.readUInt16LE(0) / 10;
        bms.ccl = d.readUInt16LE(2) / 10;
        bms.dcl = d.readUInt16LE(4) / 10;
        bms.dvl = d.readUInt16LE(6) / 10;
        decoded.name = "Limits";
        decoded.cvl = bms.cvl;
        decoded.ccl = bms.ccl;
        decoded.dcl = bms.dcl;
        decoded.dvl = bms.dvl;
        break;

    case 0x355:
        bms.soc = d.readUInt16LE(0);
        bms.soh = d.readUInt16LE(2);
        if (d.length >= 6) {
            bms.socHiRes = d.readUInt16LE(4) / 100;
        }
        decoded.name = "SOC/SOH";
        decoded.soc = bms.soc;
        decoded.soh = bms.soh;
        decoded.socHiRes = bms.socHiRes;
        break;

    case 0x356:
        bms.voltage = d.readInt16LE(0) / 100;
        bms.current = d.readInt16LE(2) / 10;
        bms.temperature = d.readInt16LE(4) / 10;
        bms.chargeCycles = d.readUInt16LE(6);
        decoded.name = "DC Bus";
        decoded.voltage = bms.voltage;
        decoded.current = bms.current;
        decoded.temperature = bms.temperature;
        decoded.power = Math.round(bms.voltage * bms.current * 10) / 10;
        decoded.chargeCycles = bms.chargeCycles;
        break;

    case 0x35E:
        bms.manufacturer = d.toString('ascii').replace(/\0/g, '');
        decoded.name = "Manufacturer";
        decoded.manufacturer = bms.manufacturer;
        break;

    case 0x35F:
        bms.chemistry = d.readUInt8(0);
        bms.hwVersion = d.readUInt8(2) + '.' + d.readUInt8(3);
        bms.fwVersion = d.readUInt16LE(4);
        decoded.name = "Version Info";
        decoded.chemistry = bms.chemistry;
        decoded.hwVersion = bms.hwVersion;
        decoded.fwVersion = bms.fwVersion;
        break;

    case 0x360:
        bms.forceCharge = d.readUInt8(0) === 0xFF;
        decoded.name = "Force Charge";
        decoded.forceCharge = bms.forceCharge;
        break;

    case 0x370:
        bms.productName = d.toString('ascii').replace(/\0/g, '');
        decoded.name = "Product Name";
        decoded.productName = bms.productName;
        break;

    case 0x371:
        bms.batteryName = d.toString('ascii').replace(/\0/g, '');
        decoded.name = "Battery Name";
        decoded.batteryName = bms.batteryName;
        break;

    case 0x372:
        bms.modulesOnline = d.readUInt16LE(0);
        bms.modulesBlockingCharge = d.readUInt16LE(2);
        bms.modulesBlockingDischarge = d.readUInt16LE(4);
        bms.modulesOffline = d.readUInt16LE(6);
        bms.nrModules = bms.modulesOnline;
        decoded.name = "Module Status";
        decoded.modulesOnline = bms.modulesOnline;
        decoded.modulesBlockingCharge = bms.modulesBlockingCharge;
        decoded.modulesBlockingDischarge = bms.modulesBlockingDischarge;
        decoded.modulesOffline = bms.modulesOffline;
        break;

    case 0x373:
        bms.minCellV = d.readUInt16LE(0) / 1000;
        bms.maxCellV = d.readUInt16LE(2) / 1000;
        bms.minCellT = d.readInt16LE(4) - 273;
        bms.maxCellT = d.readInt16LE(6) - 273;
        decoded.name = "Cell Min/Max";
        decoded.minCellV = bms.minCellV;
        decoded.maxCellV = bms.maxCellV;
        decoded.cellDeltaMv = Math.round((bms.maxCellV - bms.minCellV) * 1000);
        decoded.minCellT = bms.minCellT;
        decoded.maxCellT = bms.maxCellT;
        break;

    case 0x374: case 0x375: case 0x376: case 0x377:
        if (!bms.moduleIds) bms.moduleIds = {};
        var modId = d.toString('ascii').replace(/\0/g, '');
        bms.moduleIds[id.toString(16)] = modId;
        decoded.name = "Module ID (0x" + id.toString(16) + ")";
        decoded.moduleId = modId;
        break;

    case 0x379:
        bms.capacity = d.readUInt16LE(0);
        decoded.name = "Capacity";
        decoded.capacityAh = bms.capacity;
        break;

    case 0x380:
        bms.serial = d.toString('ascii').replace(/\0/g, '');
        decoded.name = "Serial Number";
        decoded.serial = bms.serial;
        break;

    case 0x381:
        bms.alarm381 = d.toJSON().data;
        decoded.name = "Alarms Block 2";
        decoded.rawBytes = d.toJSON().data;
        decoded.rawHex = Array.from(d).map(function(b) {
            return b.toString(16).toUpperCase().padStart(2, '0');
        }).join(' ');
        decoded.NOTE = "NOT YET DECODED — need REC-BMS alarm bit mapping";
        break;

    case 0x404:
        bms.statusByte = d.readUInt8(0);
        decoded.name = "BMS Status";
        decoded.statusByte = bms.statusByte;
        decoded.rawHex = Array.from(d).map(function(b) {
            return b.toString(16).toUpperCase().padStart(2, '0');
        }).join(' ');
        break;

    default:
        return null;
}

flow.set("bms_live", bms);

var v = bms.voltage || 0;
var i = bms.current || 0;
var s = bms.soc || 0;
node.status({
    fill: "green", shape: "dot",
    text: decoded.name + " | " + v.toFixed(1) + "V " +
          i.toFixed(1) + "A " + s + "%"
});

msg.payload = decoded;
msg.topic = decoded.canId + " " + decoded.name;
return msg;

var bms = flow.get("bms_live") || {};
var eq = flow.get("equalization") || {};
var slider = flow.get("charge_slider");
var age = bms._lastUpdate ? (Date.now() - bms._lastUpdate) : -1;
var now = Date.now();

msg.payload = {
    _meta: {
        lastUpdateAge: age >= 0 ? (age / 1000).toFixed(1) + "s" : "never",
        isLive: age >= 0 && age <= 10000
    },

    equalization: {
        active: eq.active || false,
        lastCompleted: eq.lastCompleted ? new Date(eq.lastCompleted).toISOString() : "never",
        lastCompletedAge: eq.lastCompleted ? Math.round((now - eq.lastCompleted) / 3600000) + "h ago" : "never",
        startTime: eq.active ? new Date(eq.startTime).toISOString() : null,
        elapsedMin: eq.active ? Math.round((now - eq.startTime) / 60000) + "min" : null,
        slider: slider !== undefined ? slider + "%" : "unknown",
        normalCVL: slider !== undefined ? (54.0 + (slider - 40) / 60 * 7.96).toFixed(2) + "V" : "unknown",
        eqCVL: slider !== undefined ? (54.0 + (slider - 40) / 60 * 7.96 + 0.44).toFixed(2) + "V" : "unknown"
    },

    limits: {
        cvl: bms.cvl,
        ccl: bms.ccl,
        dcl: bms.dcl,
        dvl: bms.dvl
    },

    dcBus: {
        voltage: bms.voltage,
        current: bms.current,
        power: bms.voltage && bms.current ?
            Math.round(bms.voltage * bms.current * 10) / 10 : null,
        temperature: bms.temperature
    },

    stateOfCharge: {
        soc: bms.soc,
        soh: bms.soh,
        socHiRes: bms.socHiRes,
        capacity: bms.capacity
    },

    cells: {
        minVoltage: bms.minCellV,
        maxVoltage: bms.maxCellV,
        deltaMv: bms.minCellV && bms.maxCellV ?
            Math.round((bms.maxCellV - bms.minCellV) * 1000) : null,
        minTemp: bms.minCellT,
        maxTemp: bms.maxCellT,
        nrModules: bms.nrModules,
        moduleIds: bms.moduleIds
    },

    identity: {
        manufacturer: bms.manufacturer,
        productName: bms.productName,
        batteryName: bms.batteryName,
        serial: bms.serial,
        chemistry: bms.chemistry,
        hwVersion: bms.hwVersion,
        fwVersion: bms.fwVersion
    },

    forceCharge: bms.forceCharge,

    moduleStatus: {
        online: bms.modulesOnline,
        blockingCharge: bms.modulesBlockingCharge,
        blockingDischarge: bms.modulesBlockingDischarge,
        offline: bms.modulesOffline
    },

    chargeCycles: bms.chargeCycles,

    status: {
        frame381_raw: bms.alarm381,
        statusByte: bms.statusByte,
        NOTE: "REC-BMS does not publish alarm state via CAN — no 0x35A frame"
    },

    NOT_FORWARDED_TO_DBUS: [
        "soh — virtual battery rejects /Soh",
        "socHiRes — could replace /Soc for smoother readings",
        "capacity — virtual battery rejects /Capacity",
        "consumedAmphours — virtual battery rejects /ConsumedAmphours",
        "timeToGo — virtual battery rejects /TimeToGo",
        "hwVersion — virtual battery rejects /HardwareVersion",
        "fwVersion — virtual battery rejects /FirmwareVersion",
        "serial — virtual battery rejects /Serial",
        "minCellV/maxCellV — virtual battery rejects /System/*",
        "minCellT/maxCellT — virtual battery rejects /System/*",
        "nrModules — virtual battery rejects /System/*",
        "alarm360/381 raw — need REC-BMS bit mapping",
        "statusByte — need REC-BMS status mapping",
        "moduleIds — no standard dbus path",
        "chemistry — informational only"
    ]
};

msg.topic = "Full BMS State Dump";
return msg;

var val = msg.payload;
if (typeof val !== 'number' || val < 40 || val > 100) return null;

flow.set("charge_slider", val);

var voltage = 54.0 + (val - 40) / 60 * 7.96;
node.status({
    fill: "blue", shape: "dot",
    text: val + "% → " + voltage.toFixed(2) + "V CVL"
});

return null;

var bms = flow.get("bms_live") || {};
var age = Date.now() - (bms._lastUpdate || 0);
var now = Date.now();
var live = bms._lastUpdate && (age <= 10000);

// =============================================
// STAGED FALLBACK
// =============================================
var phase, phaseName, fb;

if (live) {
    phase = 0;
    phaseName = "LIVE";
} else if (age <= 30000) {
    phase = 1;
    phaseName = "ALERT";
} else if (age <= 300000) {
    phase = 2;
    phaseName = "RESTRICT";
} else {
    phase = 3;
    phaseName = "SURVIVAL";
}

var fallback = [
    { ccl: null, dcl: null, dvl: null },
    { ccl: 0, dcl: 100, dvl: 52.0 },
    { ccl: 0, dcl: 30,  dvl: 53.0 },
    { ccl: 0, dcl: 15,  dvl: 54.0 }
];
fb = fallback[phase];

var safe = {
    cvl: 62.7, ccl: 0, dcl: 15, dvl: 54.0,
    voltage: 54.0, current: 0, temperature: 20,
    soc: 50, capacity: 1440,
    minCellV: 3.375, maxCellV: 3.375,
    nrModules: 6, minCellT: 20, maxCellT: 20
};

function v(key) {
    if (!live) return safe[key];
    return (bms[key] !== undefined && bms[key] !== null)
        ? bms[key] : safe[key];
}

// =============================================
// CVL CONTROL: SLIDER + WEEKLY EQ
// =============================================
var slider = flow.get("charge_slider");
if (slider === undefined || slider === null) slider = 100;

var sliderCVL = 54.0 + (slider - 40) / 60 * 7.96;

var eq = flow.get("equalization") || {
    lastCompleted: 0, active: false, startTime: 0
};

var SEVEN_DAYS  = 7 * 24 * 3600 * 1000;
var ONE_HOUR    = 3600 * 1000;
var EQ_BOOST    = 0.44;
var eqEligible  = live && (phase === 0);
var eqDue       = (now - eq.lastCompleted) >= SEVEN_DAYS;
var eqLabel     = "";
var finalCVL;

if (eq.active) {
    var eqElapsed = now - eq.startTime;
    if (eqElapsed >= ONE_HOUR) {
        eq.active = false;
        eq.lastCompleted = now;
        eqLabel = "EQ done";
        finalCVL = sliderCVL;
    } else if (!eqEligible) {
        eq.active = false;
        eqLabel = "EQ aborted";
        finalCVL = sliderCVL;
    } else {
        var minsLeft = Math.ceil((ONE_HOUR - eqElapsed) / 60000);
        eqLabel = "EQ " + minsLeft + "min left";
        finalCVL = sliderCVL + EQ_BOOST;
    }
} else if (eqEligible && eqDue) {
    eq.active = true;
    eq.startTime = now;
    eqLabel = "EQ starting";
    finalCVL = sliderCVL + EQ_BOOST;
} else {
    finalCVL = sliderCVL;
    if (eqEligible && !eqDue) {
        var nextEqHours = Math.round(
            (SEVEN_DAYS - (now - eq.lastCompleted)) / 3600000
        );
        eqLabel = "next EQ ~" + nextEqHours + "h";
    }
}

flow.set("equalization", eq);

var bmsCVL = live ? v("cvl") : safe.cvl;
finalCVL = Math.min(finalCVL, bmsCVL);

// =============================================
// RESOLVE FINAL VALUES
// =============================================
var ccl, dcl, dvl, cvl;
if (live) {
    ccl = v("ccl");
    dcl = v("dcl");
    dvl = v("dvl");
    cvl = finalCVL;
} else {
    ccl = fb.ccl;
    dcl = fb.dcl;
    dvl = fb.dvl;
    cvl = finalCVL;
}

var volts   = v("voltage");
var amps    = live ? v("current") : 0;
var cap     = v("capacity");
var soc     = v("soc");
var cellMin = v("minCellV");
var cellMax = v("maxCellV");

msg.payload = {
    "/Info/MaxChargeVoltage":    cvl,
    "/Info/MaxChargeCurrent":    ccl,
    "/Info/MaxDischargeCurrent": dcl,
    "/Info/BatteryLowVoltage":   dvl,

    "/Dc/0/Voltage":     volts,
    "/Dc/0/Current":     amps,
    "/Dc/0/Power":       Math.round(volts * amps * 10) / 10,
    "/Dc/0/Temperature": v("temperature"),

    "/Soc":              soc,

    "/Alarms/LowVoltage":           0,
    "/Alarms/HighVoltage":          0,
    "/Alarms/LowTemperature":       0,
    "/Alarms/HighTemperature":      0,
    "/Alarms/LowSoc":               (soc < 10) ? 2 : (soc < 20) ? 1 : 0,
    "/Alarms/HighChargeCurrent":    live ? ((bms.modulesBlockingCharge || 0) > 0 ? 1 : 0) : 0,
    "/Alarms/HighDischargeCurrent": live ? ((bms.modulesBlockingDischarge || 0) > 0 ? 1 : 0) : 0,
    "/Alarms/CellImbalance":
        live ? (((cellMax - cellMin) > 0.100) ? 2 :
               ((cellMax - cellMin) > 0.050) ? 1 : 0) : 0,
    "/Alarms/InternalFailure":      (phase >= 1) ? 2 : ((bms.modulesOffline || 0) > 0 ? 2 : 0)
};

// =============================================
// NODE STATUS
// =============================================
var color = ["green", "yellow", "blue", "red"][phase];
if (eq.active) color = "purple";
var shape = (phase === 0) ? "dot" : "ring";

var parts = [
    phaseName,
    volts.toFixed(1) + "V",
    amps.toFixed(1) + "A",
    soc + "%",
    "CVL=" + cvl.toFixed(1) + "V",
    "(" + slider + "%)",
    "CCL=" + ccl + "A",
    "DCL=" + dcl + "A"
];
if (eqLabel) parts.push(eqLabel);
if (phase >= 1) parts.push("CAN lost " + Math.round(age/1000) + "s");

node.status({ fill: color, shape: shape, text: parts.join(" | ") });

msg.topic = "dbus_publish";
return msg;

initialize:
var eq = flow.get("equalization") || { lastCompleted: 0, active: false, startTime: 0 };
eq.active = false;
flow.set("equalization", eq);

func:
var allowed = [
    "/Info/MaxChargeVoltage",
    "/Info/MaxChargeCurrent",
    "/Info/MaxDischargeCurrent",
    "/Info/BatteryLowVoltage",
    "/Dc/0/Voltage",
    "/Dc/0/Current",
    "/Dc/0/Power",
    "/Dc/0/Temperature",
    "/Soc",
    "/Alarms/LowVoltage",
    "/Alarms/HighVoltage",
    "/Alarms/LowTemperature",
    "/Alarms/HighTemperature",
    "/Alarms/LowSoc",
    "/Alarms/HighChargeCurrent",
    "/Alarms/HighDischargeCurrent",
    "/Alarms/CellImbalance",
    "/Alarms/InternalFailure"
];

var filtered = {};
var rejected = {};
var p = msg.payload;

for (var key in p) {
    if (allowed.indexOf(key) >= 0) {
        filtered[key] = p[key];
    } else {
        rejected[key] = p[key];
    }
}

var rejKeys = Object.keys(rejected);
if (rejKeys.length > 0) {
    var logged = flow.get("_rejectedLogged") || false;
    if (!logged) {
        node.warn("Filtered out paths: " + rejKeys.join(", "));
        flow.set("_rejectedLogged", true);
    }
}

var aCount = Object.keys(filtered).length;
var rCount = rejKeys.length;
node.status({
    fill: rCount > 0 ? "yellow" : "green",
    shape: "dot",
    text: aCount + " passed, " + rCount + " filtered"
});

msg.payload = filtered;
return msg;
